const canvases = {
            left: document.getElementById('canvas-left'),
            right: document.getElementById('canvas-right')
        };
        const huds = {
            left: document.getElementById('hud-left'),
            right: document.getElementById('hud-right')
        };
        const ctxs = {
            left: canvases.left.getContext('2d'),
            right: canvases.right.getContext('2d')
        };
        let traces = { left: [], right: [] };
        let animationId;
        let lastTimestamp = performance.now();
        let frameCount = 0;
        function resize() {
            Object.values(canvases).forEach(c => {
                c.width = c.offsetWidth;
                c.height = c.offsetHeight;
            });
        }
        window.addEventListener('resize', resize);
        resize();
        window.addEventListener("gamepadconnected", (e) => {
            document.getElementById('no-gamepad').classList.add('hidden');
            document.getElementById('tester-ui').classList.remove('hidden');
            document.getElementById('stat-name').innerText = e.gamepad.id.split('(')[0];
            updateLoop();
        });
        window.addEventListener("gamepaddisconnected", () => {
            document.getElementById('no-gamepad').classList.remove('hidden');
            document.getElementById('tester-ui').classList.add('hidden');
            cancelAnimationFrame(animationId);
        });
        function updateLoop() {
            const gamepads = navigator.getGamepads();
            if (!gamepads[0]) return;
            const gp = gamepads[0];
            const now = performance.now();
            // Calculate Polling Rate
            frameCount++;
            if (now - lastTimestamp >= 1000) {
                document.getElementById('stat-polling').innerText = frameCount + ' Hz';
                frameCount = 0;
                lastTimestamp = now;
            }
            // Standard Mapping: Axes 0,1 = Left Stick | Axes 2,3 = Right Stick
            processStick('left', gp.axes[0], gp.axes[1]);
            processStick('right', gp.axes[2], gp.axes[3]);
            // Simple Circularity Error Calculation logic:
            // "Your circularity error equals the percentage of points that fall outside the ideal 1.0 unit radius."
            const totalError = (Math.abs(gp.axes[0]) > 0.05 ? calculateError(gp.axes[0], gp.axes[1]) : 0);
            document.getElementById('stat-circularity').innerText = (totalError * 100).toFixed(2) + ' %';
            animationId = requestAnimationFrame(updateLoop);
        }
        function calculateError(x, y) {
            const magnitude = Math.sqrt(x * x + y * y);
            return Math.abs(1 - magnitude);
        }
        function processStick(id, x, y) {
            const ctx = ctxs[id];
            const canvas = canvases[id];
            // Update HUD
            huds[id].innerText = `X: ${x.toFixed(4)} | Y: ${y.toFixed(4)}`;
            // Draw
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            // Grid
            ctx.strokeStyle = '#1e293b';
            ctx.setLineDash([5, 5]);
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(canvas.width / 2, 0); ctx.lineTo(canvas.width / 2, canvas.height);
            ctx.moveTo(0, canvas.height / 2); ctx.lineTo(canvas.width, canvas.height / 2);
            ctx.stroke();
            ctx.setLineDash([]);
            // Center Target Crosshair
            ctx.strokeStyle = '#334155';
            ctx.beginPath();
            ctx.arc(canvas.width / 2, canvas.height / 2, 4, 0, Math.PI * 2);
            ctx.stroke();
            // Deadzone circle (0.05 reference line)
            ctx.strokeStyle = 'rgba(244, 63, 94, 0.4)';
            ctx.beginPath();
            ctx.arc(canvas.width / 2, canvas.height / 2, (canvas.width / 2) * 0.05, 0, Math.PI * 2);
            ctx.stroke();
            // Unit Circle (1.0 reference)
            ctx.strokeStyle = 'rgba(16, 185, 129, 0.2)';
            ctx.beginPath();
            ctx.arc(canvas.width / 2, canvas.height / 2, (canvas.width / 2) * 0.95, 0, Math.PI * 2);
            ctx.stroke();
            // Trace
            traces[id].push({ x, y });
            if (traces[id].length > 400) traces[id].shift();
            ctx.beginPath();
            ctx.strokeStyle = 'rgba(56, 189, 248, 0.4)';
            ctx.lineWidth = 2;
            traces[id].forEach((p, i) => {
                const drawX = (p.x + 1) * (canvas.width / 2);
                const drawY = (p.y + 1) * (canvas.height / 2);
                if (i === 0) ctx.moveTo(drawX, drawY);
                else ctx.lineTo(drawX, drawY);
            });
            ctx.stroke();
            // Current Position Indicator
            const curX = (x + 1) * (canvas.width / 2);
            const curY = (y + 1) * (canvas.height / 2);
            const isDrifting = Math.abs(x) > 0.05 || Math.abs(y) > 0.05;
            ctx.fillStyle = isDrifting ? '#f43f5e' : '#38bdf8';
            ctx.shadowBlur = 15;
            ctx.shadowColor = ctx.fillStyle;
            ctx.beginPath();
            ctx.arc(curX, curY, 8, 0, Math.PI * 2);
            ctx.fill();
            ctx.shadowBlur = 0;
            // Pulsing target effect if at rest
            if (!isDrifting) {
                const pulse = (Math.sin(Date.now() / 200) + 1) / 2;
                ctx.strokeStyle = `rgba(56, 189, 248, ${0.5 * pulse})`;
                ctx.beginPath();
                ctx.arc(curX, curY, 12 + 5 * pulse, 0, Math.PI * 2);
                ctx.stroke();
            }
        }
        function clearTrace() {
            traces.left = [];
            traces.right = [];
        }
